SELECT 
FROM attendance_rule_config r
WHERE r.tenant_id = #{tenantId}
  AND r.id = #{id}
  AND r.deleted_flag = 0

SELECT 
FROM attendance_rule_config r
WHERE r.tenant_id = #{tenantId}
  AND r.rule_code = #{ruleCode}
  AND r.deleted_flag = 0

SELECT e.id AS employee_id, e.employee_no, e.employee_name, w.workplace_name, d.department_name, r.id AS rule_id, r.rule_name, wr.effective_start_date, wr.effective_end_date, wr.rule_note, r.monthly_overtime_alert_hours, r.yearly_overtime_alert_hours, r.paid_leave_reminder_enabled, COALESCE(m.overtime_minutes, 0) AS monthly_overtime_minutes, COALESCE(y.yearly_overtime_minutes, 0) AS yearly_overtime_minutes, COALESCE(y.yearly_paid_leave_days, 0) AS yearly_paid_leave_days FROM employee e LEFT JOIN workplace w ON w.id = e.workplace_id LEFT JOIN department d ON d.id = e.department_id LEFT JOIN employee_work_rule wr ON wr.tenant_id = e.tenant_id AND wr.employee_id = e.id LEFT JOIN attendance_rule_config r ON r.tenant_id = e.tenant_id AND r.id = wr.rule_id AND r.deleted_flag = 0 LEFT JOIN attendance_monthly m ON m.tenant_id = e.tenant_id AND m.employee_id = e.id AND m.year_month = #{yearMonth} AND m.deleted_flag = 0 LEFT JOIN ( SELECT tenant_id, employee_id, SUM(overtime_minutes) AS yearly_overtime_minutes, SUM(paid_leave_days) AS yearly_paid_leave_days FROM attendance_monthly WHERE tenant_id = #{tenantId} AND year_month >= #{yearStartMonth} AND year_month <= #{yearMonth} AND deleted_flag = 0 GROUP BY tenant_id, employee_id ) y ON y.tenant_id = e.tenant_id AND y.employee_id = e.id WHERE e.tenant_id = #{tenantId}
AND ( e.employee_no LIKE CONCAT('%', #{keyword}, '%') OR e.employee_name LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(r.rule_name, '') LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY e.employee_no ASC, e.id ASC

SELECT COUNT(*)
FROM employee_work_rule
WHERE tenant_id = #{tenantId}
  AND employee_id = #{employeeId}

